mapper.select:
select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like '%' || #{search} || '%'
ORDER BY sdl.ITEM_CODE asc

select bb.bookset_id as booksetId, /*账套代码*/ bb.ITEM_CODE as subjectNo, /*科目号*/ bb.CDATE as balanceDate, /*余额日期*/ bb.ITEM_NAME as subjectName, /*科目名称*/ bb.ITEM_NAME as itemName, /*科目名称*/ NVL(bb.ITEM_AMT,0) as oAmt,/*科目余额*/ NVL(bb.ITEM_AMT,0) as endingBalance,/*期末余额*/ bb.ITEM_TYPE as itemType/*科目类型*/ from VAL_TABLE_BAS bb where bb.bookset_id = #{booksetId} and bb.CDATE = #{balanceDate} and bb.ITEM_TYPE in
#{item}
order by bb.ITEM_CODE

select bb.ITEM_CODE as subjectNo, /*科目号*/ bb.CDATE as balanceDate, /*余额日期*/ bb.ITEM_NAME as subjectName, /*科目名称*/ bb.ITEM_NAME as itemName, /*科目名称*/ SUM(bb.ITEM_AMT) as oAmt,/*科目余额*/ SUM(bb.ITEM_AMT) as endingBalance,/*期末余额*/ bb.ITEM_TYPE as itemType/*科目类型*/ FROM VAL_TABLE_BAS bb WHERE bb.CDATE = #{balanceDate} AND bb.ITEM_TYPE in
#{item}
AND (bb.bookset_id in
null) OR bb.BOOKSET_ID in (
#{item.code}
) GROUP BY bb.ITEM_CODE, bb.CDATE, bb.ITEM_NAME, bb.ITEM_TYPE ORDER BY bb.ITEM_CODE
